+using System.Text.RegularExpressions;
+
+namespace DocSummary.Services;
+
+/// <summary>
+/// A simple extractive summarizer that scores sentences by word frequency
+/// and returns the top-ranked ones in their original order.
+/// </summary>
+public partial class ExtractiveSummarizer : IDocumentSummarizer
+{
+    private static readonly HashSet<string> StopWords = new(StringComparer.OrdinalIgnoreCase)
+    {
+        "a","an","the","and","or","but","is","are","was","were","be","been",
+        "being","have","has","had","do","does","did","will","would","shall",
+        "should","may","might","must","can","could","in","on","at","to","for",
+        "of","with","by","from","as","into","through","during","before","after",
+        "above","below","between","out","off","over","under","again","further",
+        "then","once","it","its","this","that","these","those","i","me","my",
+        "we","our","you","your","he","him","his","she","her","they","them","their",
+        "what","which","who","whom","not","no","nor","so","if","up","about"
+    };
+
+    [GeneratedRegex(@"(?<=[.!?])\s+")]
+    private static partial Regex SentenceSplitter();
+
+    [GeneratedRegex(@"[^\w\s]")]
+    private static partial Regex PunctuationStripper();
+
+    public string Summarize(string documentText, int maxSentences)
+    {
+        var sentences = SentenceSplitter()
+            .Split(documentText.Trim())
+            .Where(s => !string.IsNullOrWhiteSpace(s))
+            .ToList();
+
+        if (sentences.Count <= maxSentences)
+            return string.Join(" ", sentences);
+
+        var wordFrequencies = ComputeWordFrequencies(sentences);
+
+        var scored = sentences
+            .Select((sentence, index) => (Index: index, Score: ScoreSentence(sentence, wordFrequencies)))
+            .OrderByDescending(x => x.Score)
+            .Take(maxSentences)
+            .OrderBy(x => x.Index) // preserve original order
+            .Select(x => sentences[x.Index]);
+
+        return string.Join(" ", scored);
+    }
+
+    private static Dictionary<string, int> ComputeWordFrequencies(List<string> sentences)
+    {
+        var freq = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
+        foreach (var sentence in sentences)
+        {
+            foreach (var word in ExtractWords(sentence))
+            {
+                if (!StopWords.Contains(word))
+                    freq[word] = freq.GetValueOrDefault(word) + 1;
+            }
+        }
+        return freq;
+    }
+
+    private static double ScoreSentence(string sentence, Dictionary<string, int> wordFrequencies)
+    {
+        var words = ExtractWords(sentence).ToList();
+        if (words.Count == 0)
+            return 0;
+
+        double score = words
+            .Where(w => !StopWords.Contains(w))
+            .Sum(w => wordFrequencies.GetValueOrDefault(w));
+
+        return score / words.Count;
+    }
+
+    private static IEnumerable<string> ExtractWords(string text)
+    {
+        return PunctuationStripper()
+            .Replace(text, "")
+            .Split(' ', StringSplitOptions.RemoveEmptyEntries);
+    }
+}
